'use strict';
// Adaptación de «Ventana de enlace», aportada por el equipo. Misma misión, NASA y DEM.
(function(){
 const previous=renderMission,plans=new Map();let cleanup=null;
 const restart=$('restartMission').onclick;$('restartMission').onclick=()=>{plans.clear();restart();};
 const icon=(name)=>name==='sun'?'☼':'◎';
 renderMission=function(...args){cleanup?.();cleanup=null;previous.apply(this,args);if(!journeyStarted||mission.step!==2||!RM.ready)return;
  const a=missionAnalysis();if(!a)return;const root=$('gameContent'),site=sites[mission.site],blocks=DateWindowRules.blocks(a,mission.capacity,mission.load);
  const key=JSON.stringify([site,mission.date,mission.capacity,mission.load,mission.tracking,mission.height,RM.panelHeight,RM.radius,RM.margin]);
  let selected=plans.get(key)||new Set(),hints=false,result=null,timer=null,running=false,pending=false;plans.set(key,selected);
  let hour=Math.min(167,Math.max(0,mission.previewHour));
  root.innerHTML=stageHeading('DECISIÓN 3 · EL MOMENTO','Jugá con el tiempo. Encontrá tu ventana.','Mové el reloj, mirá cómo cambia el cielo y elegí cuándo intentarías enviar noticias a casa.')+`
   <section class="window-intro"><img src="assets/felicette-comms.png" alt="Félicette te acompaña a planificar las transmisiones"><div><span class="eyebrow">FÉLICETTE TE PROPONE UN RETO</span><h2>¿Cuándo mandamos nuestra primera foto?</h2><p>Primero mirá el cielo. Después marcá uno o más bloques de seis horas para practicar. Probá tu plan y descubrí qué ayuda o qué falta.</p><small>No hace falta acertar a la primera. Las pistas están para ayudarte.</small></div></section>
   <section class="window-date-panel"><div><span class="eyebrow">EL INICIO DE TU AVENTURA</span><h2>Una fecha, siete días para explorar.</h2><p>Tu lugar elegido: <b></b>. Cambiar la fecha recalcula el mismo terreno.</p></div><label>Día de inicio · UTC<input id="gameCalendar" type="date" min="2025-01-01" max="2026-12-24" value="${mission.date.slice(0,10)}"></label><label>Hora UTC<select id="gameHour">${Array.from({length:24},(_,h)=>`<option value="${String(h).padStart(2,'0')}" ${h===+mission.date.slice(11,13)?'selected':''}>${String(h).padStart(2,'0')}:00</option>`).join('')}</select></label><button id="applyGameDate" class="primary">Explorar esta fecha →</button><p id="gameDateStatus" role="status">Fecha aplicada: ${hoursLabel(a.idx)}.</p><div class="date-shortcuts"><button data-shift-date="-7">← Una semana antes</button><button data-shift-date="7">Una semana después →</button></div></section>
   <section class="window-observatory"><div class="window-sky-main"><div class="window-panel-heading"><div><span class="eyebrow">LO QUE VE TU ROVER</span><h2>El cielo también tiene caminos.</h2></div><span id="windowClock" class="window-clock"></span></div><div id="windowSkyScene" class="window-sky-scene"></div><div class="window-time-controls"><button id="windowDayBack" aria-label="Retroceder un día">−1 día</button><button id="windowHourBack" aria-label="Retroceder seis horas">−6 h</button><button id="windowPlay">▶ Ver pasar el tiempo</button><button id="windowHourNext" aria-label="Avanzar seis horas">+6 h</button><button id="windowDayNext" aria-label="Avanzar un día">+1 día</button></div><label class="window-time-slider">Mové el tiempo de tu misión<input id="windowTime" type="range" min="0" max="167" step="1" value="${hour}"></label><div class="window-live-status"><article id="windowSunStatus"></article><article id="windowEarthStatus"></article></div></div>
   <div class="window-side"><div class="window-context"><h3>Sol, Luna y Tierra</h3><svg viewBox="0 0 360 200" role="img" aria-label="Esquema de la misión: Sol, rover sobre la Luna y Tierra. Sin escala."><defs><radialGradient id="windowSunGlow"><stop stop-color="#fff7c7"/><stop offset="1" stop-color="#e5a929"/></radialGradient></defs><circle cx="53" cy="53" r="25" fill="url(#windowSunGlow)"/><text x="53" y="97" text-anchor="middle">Sol</text><path d="M80 66L161 130" stroke="#f4ca60" stroke-width="2" stroke-dasharray="6 6"/><path d="M157 165Q204 100 267 165" fill="#5c7587"/><circle cx="212" cy="123" r="7" fill="#b5f4a6"/><path d="M223 120L290 65" stroke="#6edce9" stroke-width="2" stroke-dasharray="6 6"/><circle cx="307" cy="47" r="22" fill="#359ed1"/><path d="M292 35L307 31 319 42 306 46 312 60 299 65 291 50" fill="#b2d7a7"/><text x="307" y="90" text-anchor="middle">Tierra</text><text x="211" y="191" text-anchor="middle">Tu rover · Luna</text></svg><p>La Luna rota y las direcciones del cielo cambian. Las montañas pueden ocultar la luz o el camino a la Tierra.</p><small>Esquema ilustrativo, sin escala. Las posiciones calculadas están en el gráfico del horizonte.</small></div><div class="window-coach"><span class="eyebrow">CÓMO JUGAR</span><ol><li>Elegí una fecha y mové el reloj.</li><li>Marcá bloques para intentar comunicar.</li><li>Probá y ajustá: Félicette te cuenta qué pasó.</li></ol><button id="windowHint">✦ Mostrarme las ventanas</button><p id="windowHintText">Podés pedir pistas todas las veces que quieras.</p></div></div></section>
   <section class="window-planner"><div class="window-panel-heading"><div><span class="eyebrow">TU PLAN DE TRANSMISIONES</span><h2>Pintá los momentos de tu aventura.</h2><p>Cada botón representa seis horas. Podés tocarlo o arrastrar sobre varios.</p></div><div class="window-plan-actions"><button id="windowClear">Limpiar selección</button><button id="windowRun" class="primary">▶ Probar mi plan</button></div></div><div class="window-key"><span>○ Sin seleccionar</span><span>● Cian: elegido</span><span>☼ Amarillo: horas con luz</span><span>◎ Azul: horas con Tierra visible</span></div><div id="windowBlocks" class="window-block-days" role="group" aria-label="Elegí bloques de seis horas para transmitir"></div><p id="windowSelected" role="status"></p><div id="windowResult" class="window-result" role="status" hidden></div><div id="windowBattery" class="window-battery" hidden></div></section>
   <details class="window-method"><summary>¿Qué datos estamos usando?</summary><p>Las posiciones usan los registros horarios NASA de 2025–2026 y el horizonte del terreno real de Site01, hasta ${RM.radius/1000} km, con margen ${RM.margin}°. Cada bloque necesita las seis muestras horarias de Tierra despejada y consumo cubierto; una media favorable no alcanza.</p><p>La batería actual es ${mission.capacity} Wh, el consumo ${mission.load} W y el panel ${mission.tracking?'sigue al Sol en el modelo ideal':'está horizontal fijo'}. En la próxima decisión vas a ajustar la energía. El gráfico de batería usa el balance horario de la misión; elegir bloques no agrega un consumo de radio, ya que no se definió un transmisor separado. No estimamos GB ni velocidad de enlace.</p><p>Los estados marginales no cuentan como ventanas confirmadas. El relieve fuera del radio puede ocultar el cielo. La geometría no garantiza servicio de comunicaciones y no se simula temperatura ni un aterrizaje.</p><p>Interacciones adaptadas de «Ventana de enlace», aportada por el equipo. La integración conserva el motor común de Los Lunares.</p></details>`;
  root.querySelector('.window-date-panel b').textContent=site.name;bindGameControls();
  // Keep NASA date validation; editing a calendar does not silently apply it.
  for(const id of ['gameCalendar','gameHour']){const handler=$(id).oninput;$(id).oninput=e=>{pause();pending=true;handler(e);$('windowRun').disabled=true;$('windowSelected').textContent='Primero aplicá la fecha nueva. El cielo todavía muestra la última fecha confirmada.';};}
  function guide(title,text,pose='comms'){guideClosed=false;guideTipIndex=0;setGuideBubble(pose,title,text);}
  function stopTimer(){if(timer!==null)clearInterval(timer);timer=null;}
  function pause(){stopTimer();running=false;if($('windowPlay'))$('windowPlay').textContent='▶ Ver pasar el tiempo';if($('windowRun')){$('windowRun').disabled=pending;$('windowRun').textContent='▶ Probar mi plan';}}
  function setHour(value){hour=Math.max(0,Math.min(167,Math.round(value)));mission.previewHour=hour;$('windowTime').value=hour;drawSky();root.querySelectorAll('[data-window-block]').forEach(b=>b.classList.toggle('is-now',+b.dataset.windowBlock===Math.floor(hour/6)));}
  function drawSky(){const c=a.samples[hour];$('windowClock').textContent=hoursLabel(a.idx+hour);$('windowSkyScene').innerHTML=`<svg viewBox="0 0 600 280" role="img" aria-label="Posiciones del Sol y la Tierra respecto del horizonte local real">${horizonMarkup(site,mission.height,c)}</svg>`;
   for(const [name,key] of [['sun','sv'],['earth','ev']]){const el=$('window'+(name==='sun'?'Sun':'Earth')+'Status'),body=c[name],state=c[name==='sun'?'sstate':'estate'];el.className=c[key]?'window-visible':'window-hidden';el.innerHTML=`<span>${icon(name)} ${name==='sun'?'Sol':'Tierra'}</span><strong>${c[key]?'Ventana confirmada':state==='uncertain'?'Cerca del horizonte':'Sin ventana confirmada'}</strong><small>Elevación ${body.el.toFixed(1)}° · azimut ${body.az.toFixed(1)}°</small>`;}
  }
  function renderBlocks(){const grid=$('windowBlocks');grid.replaceChildren();for(let d=0;d<7;d++){const day=document.createElement('div');day.className='window-day';const title=document.createElement('h3');title.textContent='Día '+(d+1);day.append(title);
    for(let k=0;k<4;k++){const b=blocks[d*4+k],button=document.createElement('button');button.type='button';button.dataset.windowBlock=b.index;button.className='window-slot';button.setAttribute('aria-pressed',String(selected.has(b.index)));button.classList.toggle('chosen',selected.has(b.index));button.classList.toggle('is-now',b.index===Math.floor(hour/6));const start=new Date(Date.UTC(2025,0,1,a.idx+b.start)),end=new Date(Date.UTC(2025,0,1,a.idx+b.end));const time=n=>String(n.getUTCHours()).padStart(2,'0')+':00';button.innerHTML=`<span>${selected.has(b.index)?'●':'○'} ${time(start)}</span><small>${start.toLocaleDateString('es-AR',{timeZone:'UTC',day:'2-digit',month:'2-digit'})} · UTC</small><small>hasta ${time(end)}</small>`;
     button.setAttribute('aria-label',`${start.toISOString().slice(0,16).replace('T',' ')} UTC, seis horas${selected.has(b.index)?', seleccionado':''}${hints?`, Tierra ${b.earthHours} de 6 horas; Sol ${b.sunHours} de 6 horas`:''}`);
     if(hints){const line=document.createElement('small');line.className='window-slot-hints';line.innerHTML=`<span class="window-earth-hint">◎ ${b.earthHours}/6 h</span><span class="window-sun-hint">☼ ${b.sunHours}/6 h</span>`;button.append(line);}
     if(result&&selected.has(b.index))button.classList.add(b.compatible?'window-good':'window-review');
     button.onclick=()=>{if(suppressClick){suppressClick=false;return;}edit(b.index);};day.append(button);
    }grid.append(day);}
   $('windowSelected').textContent=pending?'Aplicá la fecha para recalcular antes de probar.':`${selected.size} bloque${selected.size===1?'':'s'} elegido${selected.size===1?'':'s'} · ${selected.size*6} horas propuestas. Esta selección es una práctica, no una reserva de enlace.`;
  }
  function edit(i,paint){if(running||pending)return;result=null;$('windowResult').hidden=true;$('windowBattery').hidden=true;const select=paint===undefined?!selected.has(i):paint;if(select)selected.add(i);else selected.delete(i);renderBlocks();setHour(blocks[i].start);}
  let drag=null,suppressClick=false;const grid=$('windowBlocks');grid.addEventListener('pointerdown',e=>{suppressClick=false;const b=e.target.closest('[data-window-block]');if(!b||running||pending)return;drag={id:e.pointerId,paint:!selected.has(+b.dataset.windowBlock),last:+b.dataset.windowBlock};});
  grid.addEventListener('pointerover',e=>{if(!drag||e.pointerId!==drag.id)return;const b=e.target.closest('[data-window-block]');if(!b||+b.dataset.windowBlock===drag.last)return;const i=+b.dataset.windowBlock;suppressClick=true;edit(drag.last,drag.paint);edit(i,drag.paint);drag.last=i;});
  const endDrag=()=>drag=null;window.addEventListener('pointerup',endDrag);window.addEventListener('pointercancel',endDrag);
  $('windowTime').oninput=e=>{pause();setHour(+e.target.value);};for(const [id,delta]of [['windowDayBack',-24],['windowHourBack',-6],['windowHourNext',6],['windowDayNext',24]])$(id).onclick=()=>{pause();setHour(hour+delta);};
  $('windowPlay').onclick=()=>{if(timer!==null){pause();return;}if(hour===167)setHour(0);$('windowPlay').textContent='❚❚ Pausar el tiempo';timer=setInterval(()=>{if(hour>=167){pause();return;}setHour(hour+1);},matchMedia('(prefers-reduced-motion: reduce)').matches?1000:400);};
  $('windowHint').onclick=()=>{hints=!hints;$('windowHint').textContent=hints?'Ocultar pistas':'✦ Mostrarme las ventanas';$('windowHintText').textContent=hints?'Azul: horas de Tierra visible. Amarillo: horas con Sol. Un bloque parcial puede cortar la transmisión.':'Podés pedir pistas todas las veces que quieras.';renderBlocks();guide('¡Miremos las pistas juntas!','Buscá bloques con 6 de 6 horas de Tierra visible. Después revisamos si la batería cubre el consumo. Pedir ayuda también es aprender.');};
  $('windowClear').onclick=()=>{pause();selected.clear();result=null;renderBlocks();$('windowResult').hidden=true;$('windowBattery').hidden=true;};
  function finish(){pause();result=DateWindowRules.assess(blocks,selected);renderBlocks();const box=$('windowResult');box.hidden=false;box.className='window-result '+(result.complete?'window-success':'window-try');box.replaceChildren();const title=document.createElement('h3');title.textContent=result.complete?'¡Encontraste una ventana para practicar!':'¡Probemos otro horario!';const p=document.createElement('p');p.textContent=`${result.good.length} de ${result.selected} bloques cumplen visibilidad y energía durante sus seis horas. `+(result.complete?'Podés seguir con tu misión y ajustar la energía en el próximo paso.':'Félicette te ayuda a entender qué cambiar.');box.append(title,p);
   for(const i of result.review){const b=blocks[i],p=document.createElement('p');p.textContent=`${hoursLabel(a.idx+b.start)}: `+(b.earthHours<6?`la Tierra tiene ${b.earthHours}/6 horas de ventana confirmada. `:'')+(b.poweredHours<6?`El consumo está cubierto en ${b.poweredHours}/6 horas con la batería actual. Podrás ajustarla en energía.`:'');box.append(p);}
   const retry=document.createElement('button');retry.textContent='Volver a elegir horarios';retry.onclick=()=>{result=null;box.hidden=true;renderBlocks();guide('Ahora sabemos qué buscar.','Podés desmarcar bloques y probar otros. Cambiar la fecha o la batería también cambia las oportunidades.');};box.append(retry);
   const points=[mission.capacity,...a.budget.rows.map(r=>r.storedWh)].map((v,i)=>`${30+i/168*540},${110-v/mission.capacity*85}`).join(' ');$('windowBattery').hidden=false;$('windowBattery').innerHTML=`<h3>Así evoluciona tu batería actual</h3><svg viewBox="0 0 600 140" role="img" aria-label="Energía almacenada en la batería durante siete días"><path d="M30 20V110H570" stroke="#698294" fill="none"/><polyline points="${points}" fill="none" stroke="#9cedb0" stroke-width="3"/><text x="30" y="135" fill="#bdd3de">Inicio</text><text x="490" y="135" fill="#bdd3de">Siete días</text></svg><p>${mission.capacity} Wh utilizables · mínimo ${Math.round(a.budget.minStoredWh)} Wh · consumo sin cubrir ${Math.round(a.budget.unservedWh)} Wh. Elegir horarios no cambia este balance: todavía no agregamos un modelo de potencia del transmisor.</p>`;
   guide(result.complete?'¡Buen trabajo, explorador!':'¡Oh! Ese horario necesita un ajuste.',result.complete?'Tu plan encontró bloques completos con Tierra despejada y energía en el modelo. La visibilidad no garantiza un servicio de radio real.':result.review.some(i=>blocks[i].earthHours<6)?'En algunos bloques la Tierra se esconde detrás del horizonte. Activá las pistas y probá un horario con seis horas de ventana.':'La batería actual no alcanza en esos momentos. Podemos probar otro horario o ajustar la energía en el siguiente paso.');
  }
  $('windowRun').onclick=()=>{if(pending||running)return;if(!selected.size){guide('Primero pintemos un horario.','Tocá un bloque de seis horas en el tablero. Si necesitás una pista, te muestro cuándo se ve la Tierra.');$('windowSelected').textContent='Elegí al menos un bloque antes de probar tu plan.';return;}pause();if(matchMedia('(prefers-reduced-motion: reduce)').matches){finish();return;}running=true;$('windowRun').disabled=true;$('windowRun').textContent='Recorriendo tu plan…';let i=0;timer=setInterval(()=>{setHour(i*6);i++;if(i===28)finish();},100);};
  const visibility=()=>{if(document.hidden)pause();};document.addEventListener('visibilitychange',visibility);const route=()=>{if(location.hash!=='#mission')pause();};window.addEventListener('hashchange',route);
  cleanup=()=>{stopTimer();window.removeEventListener('pointerup',endDrag);window.removeEventListener('pointercancel',endDrag);window.removeEventListener('hashchange',route);document.removeEventListener('visibilitychange',visibility);};
  renderBlocks();drawSky();if(missionFeedback)updateFloatingGuide();else guide('¡Ahora elegimos el momento!','Mové el reloj para ver el Sol y la Tierra sobre las montañas. Después pintá los horarios en los que intentarías mandar nuestra primera foto.');
 };
 if(journeyStarted)renderMission();
})();
